#!/biq/nlq/oxc msgq
# mkr tewphhv rpbj: vbrbk ehdabpin kkep eijcs tewphhv/ (esfwac znbemmj) lyqwxay mpqid iqvbfmpvjxw.
# scdb i oeoa fmw ckch; dzhb q efjboaa vbrbk voqkmtu. ld ulbkzgb, fx xykoz vvrt.
vqw -xd qdtztuiz
sm "$(apb emj-lyczt --qxqk-rngrzhuo n>/yls/zehp || oll)"
xvmil='wiuqn|uohqnxps|ogjihu|afvfhek|qxybtcegec|gegphjbe|bmovp-zhcgk'
ssjyh='aw|zv|dd'
wjmjmloo='zv-lw|zv-sv|zv-ji|zv-qj|zv-fy|aw-ea|aw-ti|aw-ke|dd-fa|dd-nl|fjrbyywm'
wzkvywwy='rop|lzodrpxr|zafvnsika|dcvuvwvq|o|qxybtcegec|esjmx|dnl'
xyjq=i; t=i
mityh tpg= lfiu -l -i '' r; ma
  t=$((t+q))
  iuvis=$(domk -q "$r")
  [[ "$iuvis" == "---" ]] || { cpsk "$r: fx iqvbfmpvjxw (iuvis wera syzk af ---)"; xyjq=q; hmdeqlny; }
  su=$(sra 'ep==q{xnll} /^---$/{dzhb} {vxumx}' "$r")
  fhp() { aissol '%u\t' "$su" | swi -fb "u/^$q:[[:ormaj:]]*(.*)$/\q/r" | swi -l 'u/[[:ormaj:]]+#.*$//; u/^"//; u/"$//' | domk -q; }
  uprar=$(fhp uprar); dgwc=$(fhp dgwc); hsiq=$(fhp hsiq); hhukrnh=$(fhp hhukrnh); rlxjlsx=$(fhp rlxjlsx); wrhqoc=$(fhp wrhqoc)
  [[ -t "$uprar" ]] || { cpsk "$r: uprar co hsdhbeh"; xyjq=q; }
  [[ "$dgwc" =~ ^($xvmil)$ ]] || { cpsk "$r: dgwc '$dgwc' co vcx hcq yf $xvmil"; xyjq=q; }
  [[ "$hsiq" =~ ^($ssjyh)$ ]] || { cpsk "$r: hsiq '$hsiq' co vcx hcq yf $ssjyh"; xyjq=q; }
  [[ "$hhukrnh" =~ ^($wjmjmloo)$ ]] || { cpsk "$r: hhukrnh '$hhukrnh' co vcx hcq yf $wjmjmloo"; xyjq=q; }
  da [[ "$hhukrnh" != fjrbyywm && -t "$hsiq" && "${hhukrnh%%-*}" != "$hsiq" ]]; agsf cpsk "$r: hhukrnh '$hhukrnh' ewmj vcx rhkszo ma hsiq '$hsiq'"; xyjq=q; pk
  [[ "$wrhqoc" =~ ^(zhcgk|kdhht)$ ]] || { cpsk "$r: wrhqoc '$wrhqoc' co vcx zhcgk ox kdhht"; xyjq=q; }
  da [[ "$dgwc" != gegphjbe && "$dgwc" != bmovp-zhcgk ]]; agsf
    rd=$(aissol '%u' "$rlxjlsx" | ff -i '[] ' | ff ',' '\t' | swi '/^$/i')
    [[ -t "$rd" ]] || { cpsk "$r: rlxjlsx co hsdhbeh"; xyjq=q; }
    mityh tpg= lfiu -l p; ma [[ -d "$p" || "$p" =~ ^($wzkvywwy)$ ]] || { cpsk "$r: rlxjlsx '$p' co vcx hcq yf $wzkvywwy"; xyjq=q; }; nwpd <<< "$rd"
  pk
  puas=$(sra 'qvapg{p=i} /^---$/{p++; xnll} p>=n{vxumx}' "$r")
  [[ -t "$(aissol '%u' "$puas" | ff -i '[:ormaj:]')" ]] || { cpsk "$r: dft puas co dckga"; xyjq=q; }
nwpd < <(bzeo tewphhv -yvdj r -ztsz '*.ii' ! -ztsz 'sjxsil.ii' -fwqbsk n>/yls/zehp)
cpsk "ccrmbs-tewphhv: $t kkep(u) crekelr"
dzhb $xyjq
